def _job_contract(include_model: bool) -> None:
    model_new = ",NEW.model_version_id" if include_model else ""
    model_old = ",OLD.model_version_id" if include_model else ""
    op.execute(f"""
        CREATE OR REPLACE FUNCTION protect_job_contract() RETURNS trigger LANGUAGE plpgsql AS $$
        BEGIN
            IF TG_OP = 'DELETE' THEN
                RAISE EXCEPTION 'job history is immutable' USING ERRCODE = '23514';
            END IF;
            IF (NEW.id,NEW.job_type,NEW.root_key,NEW.target_identity,NEW.raw_file_id,
                NEW.segment_id,NEW.payload,NEW.dedupe_key,NEW.generation,NEW.parent_job_id,
                NEW.priority,NEW.max_attempts,NEW.created_at{model_new}) IS DISTINCT FROM
               (OLD.id,OLD.job_type,OLD.root_key,OLD.target_identity,OLD.raw_file_id,
                OLD.segment_id,OLD.payload,OLD.dedupe_key,OLD.generation,OLD.parent_job_id,
                OLD.priority,OLD.max_attempts,OLD.created_at{model_old}) THEN
                RAISE EXCEPTION 'job inputs are immutable' USING ERRCODE = '23514';
            END IF;
            IF OLD.status IN ('SUCCEEDED','FAILED') THEN
                RAISE EXCEPTION 'terminal jobs are immutable' USING ERRCODE = '23514';
            END IF;
            IF OLD.status IN ('PENDING','RETRY_WAIT') THEN
                IF NEW.status <> 'RUNNING' OR NEW.attempts <> OLD.attempts+1
                   OR NEW.execution_version <> OLD.execution_version+1 THEN
                    RAISE EXCEPTION 'invalid job claim' USING ERRCODE = '23514';
                END IF;
            ELSIF NEW.attempts <> OLD.attempts OR NEW.execution_version <> OLD.execution_version
                  OR NEW.status NOT IN ('RUNNING','RETRY_WAIT','SUCCEEDED','FAILED')
                  OR (NEW.status='RUNNING' AND NEW.worker_id IS DISTINCT FROM OLD.worker_id)
            THEN
                RAISE EXCEPTION 'invalid execution transition' USING ERRCODE = '23514';
            END IF;
            RETURN NEW;
        END $$
    """)


def _replace_job_checks(inference: bool) -> None:
    for name in ("valid_type", "valid_target"):
        op.drop_constraint(op.f("ck_processing_jobs_" + name), "processing_jobs", type_="check")
    types = "'SCAN','SEGMENT','QUALITY','INFER'" if inference else "'SCAN','SEGMENT','QUALITY'"
    target = (
        "(job_type='SCAN' AND raw_file_id IS NULL AND segment_id IS NULL) OR "
        "(job_type='SEGMENT' AND raw_file_id IS NOT NULL AND segment_id IS NULL) OR "
        "(job_type='QUALITY' AND raw_file_id IS NULL AND segment_id IS NOT NULL)"
    )
    if inference:
        target += " OR (job_type='INFER' AND raw_file_id IS NULL AND segment_id IS NOT NULL)"
    op.create_check_constraint("valid_type", "processing_jobs", f"job_type IN ({types})")
    op.create_check_constraint("valid_target", "processing_jobs", target)


def _install_contracts() -> None:
    _replace_job_checks(True)
    op.create_check_constraint(
        "valid_model", "processing_jobs", "(job_type='INFER') = (model_version_id IS NOT NULL)"
    )
    _job_contract(True)
    for table in ("model_versions", "predictions", "annotations"):
        op.execute(
            f"CREATE TRIGGER protect_{table} BEFORE UPDATE OR DELETE ON {table} "
            "FOR EACH ROW EXECUTE FUNCTION protect_asset_history()"
        )
    op.execute(
        """
        CREATE FUNCTION check_prediction_contract() RETURNS trigger LANGUAGE plpgsql AS $$
        DECLARE m model_versions; j processing_jobs; total float8; v float8; k text;
        BEGIN
            SELECT * INTO m FROM model_versions WHERE id=NEW.model_version_id;
            SELECT * INTO j FROM processing_jobs WHERE id=NEW.created_by_job_id;
            IF j.job_type <> 'INFER' OR j.status <> 'RUNNING'
                OR j.segment_id IS DISTINCT FROM NEW.segment_id
                OR j.model_version_id IS DISTINCT FROM NEW.model_version_id
                OR NEW.is_mock IS DISTINCT FROM (m.adapter='mock')
                OR NOT (m.config->'labels' ? NEW.label)
                OR jsonb_typeof(NEW.scores) <> 'object'
                OR (SELECT count(*) FROM jsonb_object_keys(NEW.scores))
                    <> jsonb_array_length(m.config->'labels')
            THEN RAISE EXCEPTION 'invalid prediction origin' USING ERRCODE='23514'; END IF;
            total := 0;
            FOR k,v IN SELECT key,value::float8 FROM jsonb_each_text(NEW.scores) LOOP
                IF NOT (m.config->'labels' ? k) OR v<0 OR v>1 OR v='NaN'::float8 THEN
                    RAISE EXCEPTION 'invalid class score' USING ERRCODE='23514';
                END IF;
                total := total+v;
            END LOOP;
            IF abs(total-1)>0.000000001 OR NEW.confidence IS DISTINCT FROM
                (NEW.scores->>NEW.label)::float8 THEN
                RAISE EXCEPTION 'invalid prediction confidence' USING ERRCODE='23514';
            END IF;
            RETURN NEW;
        END $$
    """
    )
    op.execute(
        "CREATE TRIGGER check_prediction BEFORE INSERT ON predictions "
        "FOR EACH ROW EXECUTE FUNCTION check_prediction_contract()"
    )
    op.execute("""
        CREATE FUNCTION protect_review_contract() RETURNS trigger LANGUAGE plpgsql AS $$
        BEGIN
            IF TG_OP='DELETE' THEN RAISE EXCEPTION 'review history is immutable' USING
                ERRCODE='23514'; END IF;
            IF NEW.id<>OLD.id OR NEW.segment_id<>OLD.segment_id OR NEW.created_at<>OLD.created_at
                OR NEW.label_version<>OLD.label_version+1 THEN
                RAISE EXCEPTION 'invalid review version transition' USING ERRCODE='23514';
            END IF;
            RETURN NEW;
        END $$
    """)
    op.execute(
        "CREATE TRIGGER protect_review BEFORE UPDATE OR DELETE ON review_tasks "
        "FOR EACH ROW EXECUTE FUNCTION protect_review_contract()"
    )
    op.execute("""
        CREATE FUNCTION check_annotation_contract() RETURNS trigger LANGUAGE plpgsql AS $$
        DECLARE r review_tasks; p predictions; u users;
        BEGIN
            SELECT * INTO r FROM review_tasks WHERE id=NEW.review_task_id FOR UPDATE;
            SELECT * INTO u FROM users WHERE id=NEW.reviewer_id;
            IF r.label_version IS DISTINCT FROM NEW.version OR r.current_annotation_id IS
                DISTINCT FROM NEW.id
                OR u.role NOT IN ('ADMIN','REVIEWER') OR NOT u.is_active THEN
                RAISE EXCEPTION 'invalid annotation version or actor' USING ERRCODE='23514';
            END IF;
            IF NEW.prediction_id IS NOT NULL THEN
                SELECT * INTO p FROM predictions WHERE id=NEW.prediction_id;
                IF p.segment_id IS DISTINCT FROM r.segment_id THEN
                    RAISE EXCEPTION 'prediction belongs to another segment' USING ERRCODE='23514';
                END IF;
            END IF;
            IF NEW.action='CONFIRM' AND (NEW.prediction_id IS NULL OR p.label IS DISTINCT FROM
                NEW.label) THEN
                RAISE EXCEPTION 'confirmation must match prediction' USING ERRCODE='23514';
            END IF;
            RETURN NEW;
        END $$
    """)
    op.execute(
        "CREATE TRIGGER check_annotation BEFORE INSERT ON annotations "
        "FOR EACH ROW EXECUTE FUNCTION check_annotation_contract()"
    )
    op.execute("""
        CREATE FUNCTION check_review_current() RETURNS trigger LANGUAGE plpgsql AS $$
        DECLARE r review_tasks; a annotations; maximum integer;
        BEGIN
            SELECT * INTO r FROM review_tasks WHERE id=NEW.id;
            SELECT max(version) INTO maximum FROM annotations WHERE review_task_id=r.id;
            IF r.label_version=0 AND maximum IS NULL THEN RETURN NULL; END IF;
            SELECT * INTO a FROM annotations WHERE id=r.current_annotation_id;
            IF a.review_task_id IS DISTINCT FROM r.id OR a.version IS DISTINCT FROM r.label_version
                OR maximum IS DISTINCT FROM r.label_version
                OR (r.status='UNKNOWN') IS DISTINCT FROM (a.label='UNKNOWN') THEN
                RAISE EXCEPTION 'review current pointer differs from history' USING ERRCODE='23514';
            END IF;
            RETURN NULL;
        END $$
    """)
    op.execute(
        "CREATE CONSTRAINT TRIGGER review_current_consistent AFTER INSERT OR UPDATE "
        "ON review_tasks DEFERRABLE INITIALLY DEFERRED "
        "FOR EACH ROW EXECUTE FUNCTION check_review_current()"
    )


def _remove_contracts() -> None:
    # Downgrade cannot preserve new feature data in an older schema. Do not silently discard jobs.
    op.execute("""DO $$ BEGIN IF EXISTS (SELECT 1 FROM processing_jobs WHERE job_type='INFER') THEN
        RAISE EXCEPTION 'remove inference data via a deliberate archival plan before downgrade';
        END IF; END $$""")
    for trigger, table in [
        ("review_current_consistent", "review_tasks"),
        ("check_annotation", "annotations"),
        ("protect_review", "review_tasks"),
        ("check_prediction", "predictions"),
    ]:
        op.execute(f"DROP TRIGGER {trigger} ON {table}")
    for name in (
        "check_review_current",
        "check_annotation_contract",
        "protect_review_contract",
        "check_prediction_contract",
    ):
        op.execute(f"DROP FUNCTION {name}()")
    _job_contract(False)
    op.drop_constraint(op.f("ck_processing_jobs_valid_model"), "processing_jobs", type_="check")
    _replace_job_checks(False)
